), ready AS (
 SELECT 1 WHERE (SELECT COUNT(*) FROM items WHERE status IN ('live','draft'))=156
 AND NOT EXISTS(SELECT 1 FROM approved a LEFT JOIN items i ON i.sku=a.sku
  WHERE i.sku IS NULL OR i.version<>a.version OR i.status<>a.status
   OR i.price_usd NOT IN (a.previous_price,a.maximum_usdc))
 AND NOT EXISTS(SELECT 1 FROM component_releases r JOIN approved a ON a.sku=r.sku AND a.version=r.version)
 AND NOT EXISTS(SELECT 1 FROM payload_objects r JOIN approved a ON a.sku=r.sku AND a.version=r.version)
 AND NOT EXISTS(SELECT 1 FROM product_routing_manifests r JOIN approved a ON a.sku=r.sku AND a.version=r.version)
)
UPDATE items SET price_usd=(SELECT maximum_usdc FROM approved WHERE sku=items.sku),
 updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE EXISTS(SELECT 1 FROM ready) AND sku IN (SELECT sku FROM approved)
 AND price_usd<>(SELECT maximum_usdc FROM approved WHERE sku=items.sku);
